/**
 * Ordered schema migrations (Postgres dialect). Index = version number. Append-only: NEVER edit
 * or reorder a shipped entry; add a new one to evolve. Mirrors the legacy sqlite/luo.sql blob +
 * indexed scalar-overlay shape, collapsed to the numero-keyed Tier-0 subset (parallel to
 * @penni/storage-sqlite). `*snt` are BIGINT cents; ids are GENERATED BY DEFAULT AS IDENTITY.
 */
export const SCHEMA_VERSIONS: readonly string[] = [
  `
  CREATE TABLE asetus (
    avain    TEXT PRIMARY KEY,
    arvo     TEXT,
    muokattu INTEGER NOT NULL DEFAULT 0
  );

  CREATE TABLE tili (
    numero   INTEGER PRIMARY KEY,
    tyyppi   TEXT NOT NULL,
    json     TEXT NOT NULL,
    muokattu INTEGER NOT NULL DEFAULT 0
  );

  CREATE TABLE tilikausi (
    alkaa  TEXT PRIMARY KEY,
    loppuu TEXT NOT NULL,
    json   TEXT NOT NULL
  );

  CREATE TABLE tosite (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pvm      TEXT,
    tyyppi   INTEGER NOT NULL DEFAULT 0,
    tila     INTEGER NOT NULL DEFAULT 100,
    tunniste INTEGER NOT NULL DEFAULT 0,
    sarja    TEXT NOT NULL DEFAULT '',
    kumppani INTEGER,
    viite    TEXT,
    laskupvm TEXT,
    erapvm   TEXT,
    json     TEXT NOT NULL
  );
  CREATE INDEX idx_tosite_pvm      ON tosite(pvm);
  CREATE INDEX idx_tosite_tyyppi   ON tosite(tyyppi);
  CREATE INDEX idx_tosite_tila     ON tosite(tila);
  CREATE INDEX idx_tosite_tunniste ON tosite(tunniste);
  CREATE INDEX idx_tosite_sarja    ON tosite(sarja);
  CREATE INDEX idx_tosite_kumppani ON tosite(kumppani);
  CREATE INDEX idx_tosite_viite    ON tosite(viite);

  CREATE TABLE vienti (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tosite    BIGINT NOT NULL REFERENCES tosite(id) ON DELETE CASCADE,
    rivi      INTEGER NOT NULL,
    tili      INTEGER NOT NULL,
    pvm       TEXT NOT NULL,
    debetsnt  BIGINT NOT NULL DEFAULT 0,
    kreditsnt BIGINT NOT NULL DEFAULT 0,
    kohdennus INTEGER NOT NULL DEFAULT 0,
    eraid     BIGINT
  );
  CREATE INDEX idx_vienti_tosite    ON vienti(tosite);
  CREATE INDEX idx_vienti_pvm       ON vienti(pvm);
  CREATE INDEX idx_vienti_tili      ON vienti(tili);
  CREATE INDEX idx_vienti_kohdennus ON vienti(kohdennus);

  CREATE TABLE loki (
    id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tosite BIGINT NOT NULL,
    aika   TEXT NOT NULL,
    userid INTEGER,
    tila   INTEGER NOT NULL,
    data   TEXT
  );
  CREATE INDEX idx_loki_tosite ON loki(tosite);
  `,
  // v1: kumppani (partner) — json blob + nimi/alvtunnus scalar overlay
  `
  CREATE TABLE kumppani (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nimi      TEXT,
    alvtunnus TEXT,
    json      TEXT NOT NULL
  );
  CREATE INDEX idx_kumppani_nimi ON kumppani(nimi);
  `,
  // v2: liite (attachment) — blob-hyötykuorma + metatieto-overlay, avaimena tosite
  `
  CREATE TABLE liite (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tosite    BIGINT NOT NULL REFERENCES tosite(id) ON DELETE CASCADE,
    nimi      TEXT NOT NULL,
    roolinimi TEXT,
    tyyppi    TEXT NOT NULL,
    sha       TEXT,
    luotu     TEXT NOT NULL,
    data      BYTEA NOT NULL,
    json      TEXT NOT NULL
  );
  CREATE INDEX idx_liite_tosite ON liite(tosite);
  CREATE UNIQUE INDEX idx_liite_tosite_rooli ON liite(tosite, roolinimi);
  `,
  // v3: tili avataan (numero, taso) -yhdistelmäavaimeksi — Kitsas sallii otsikon ja tilin, tai
  // kaksi otsikkoa eri tasoilla, jakaa saman numeron. Postgres voi muuttaa primaariavaimen
  // paikallaan (ALTER TABLE), joten taulua ei tarvitse SQLiten tapaan rakentaa uudelleen.
  // CASE-lauseke peilaa tasoTyypistaa (@penni/engine): lehtitilit tasolle 0, 'H<n>' otsikot
  // tasolle n. Regex-muotoinen (ei substr+CAST kuten SQLite-versiossa), koska Postgresin CAST
  // heittää virheen tyhjästä merkkijonosta (esim. paljas 'H' ilman numeroa) — SQLite palauttaisi
  // hiljaa 0:n. SCHEMA_VERSIONS[0] jätetään koskematta: append-only, ei muokata jo ajettua entryä.
  `
  ALTER TABLE tili ADD COLUMN taso INTEGER NOT NULL DEFAULT 0;
  UPDATE tili SET taso = CASE
    WHEN tyyppi ~ '^H[0-9]+' THEN CAST(substring(tyyppi FROM '^H([0-9]+)') AS INTEGER)
    ELSE 0
  END;
  ALTER TABLE tili DROP CONSTRAINT tili_pkey;
  ALTER TABLE tili ADD PRIMARY KEY (numero, taso);
  `,
  // v4: loki saa lahde-sarakkeen — agentti/työkalu-attribuutio auditriville (esim. "cli").
  // Peilaa @penni/storage-sqlite-core v4:ää.
  'ALTER TABLE loki ADD COLUMN lahde TEXT;',
];
